/* getconf (UTIL-5, plan/utilities.md section 2.3; POSIX getconf(1), getconf(1)): a front end over
 * Liella's sysconf, confstr and pathconf. The name table (getconf-names.h) is generated by
 * `cargo xtask so` from spec/abi/getconf.tsv and spec/abi/sysconf.tsv, the table Liella's own
 * sysconf, confstr and pathconf answer from (D-24.6), so a value here is always the library's.
 *
 * Behaviour settled by black-box probes of the reference (validation/transcripts/getconf):
 *   getconf [-v SPEC] NAME          a sysconf or confstr name; -1 from sysconf prints "undefined"
 *                                   (ULONG_MAX, printed unsigned, prints its number)
 *   getconf [-v SPEC] NAME PATH     a pathconf name (it needs PATH; the others refuse one)
 *   getconf [-v SPEC] -a [PATH]     every listed name, "%-35s" then the value (PATH default "/")
 * SPEC (`-v SPEC` or `-vSPEC`) is accepted and has no effect; `--` may follow it. Unknown name:
 * "Unrecognized variable", status 2; wrong operand count: the usage text, status 2; a pathconf
 * error: "getconf: pathconf: PATH: <strerror>", status 3. */
#include <errno.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

long sysconf(int name);
size_t confstr(int name, char *buf, size_t len);
long pathconf(const char *path, int name);

enum kind { SC, CS, PC };

struct name {
    const char *name;
    unsigned char kind;
    unsigned char listed;
    unsigned char is_unsigned; /* the value is printed as unsigned long (ULONG_MAX) */
    int constant;
};

/* A sysconf or pathconf value: empty (in the listing) or "undefined" for -1, except for a value
 * printed as unsigned, whose -1 is the number itself. */
static void print_long(const struct name *e, long v, const char *undefined) {
    if (e->is_unsigned)
        printf("%lu", (unsigned long)v);
    else if (v == -1)
        fputs(undefined, stdout);
    else
        printf("%ld", v);
}

#include "getconf-names.h"

static int usage(void) {
    fputs("Usage: getconf [-v specification] variable_name [pathname]\n"
          "       getconf -a [pathname]\n",
          stderr);
    return 2;
}

static const struct name *lookup(const char *s) {
    for (size_t i = 0; i < sizeof names / sizeof names[0]; i++)
        if (strcmp(names[i].name, s) == 0)
            return &names[i];
    return NULL;
}

/* A confstr value printed whole, however long. */
static void print_confstr(int constant) {
    size_t n = confstr(constant, NULL, 0);
    if (n == 0)
        return;
    char *buf = malloc(n);
    if (buf == NULL) {
        perror("getconf");
        exit(3);
    }
    confstr(constant, buf, n);
    fputs(buf, stdout);
    free(buf);
}

static int list_all(const char *path) {
    for (size_t i = 0; i < sizeof names / sizeof names[0]; i++) {
        const struct name *e = &names[i];
        if (!e->listed)
            continue;
        printf("%-35s", e->name);
        if (e->kind == CS) {
            print_confstr(e->constant);
        } else {
            print_long(e, e->kind == SC ? sysconf(e->constant) : pathconf(path, e->constant), "");
        }
        putchar('\n');
    }
    return 0;
}

static int help(void) {
    fputs("Usage: getconf [-v SPEC] VAR\n"
          "  or:  getconf [-v SPEC] PATH_VAR PATH\n"
          "\n"
          "Get the configuration value for variable VAR, or for variable PATH_VAR\n"
          "for path PATH.  If SPEC is given, give values for compilation\n"
          "environment SPEC.\n",
          stdout);
    return 0;
}

static int version(void) {
    char buf[64];
    size_t n = confstr(2 /* _CS_GNU_LIBC_VERSION */, buf, sizeof buf);
    const char *v = n > 0 && n <= sizeof buf ? buf : "";
    const char *sp = strchr(v, ' ');
    printf("getconf (Liella) %s\n", sp ? sp + 1 : v);
    return 0;
}

int main(int argc, char **argv) {
    int i = 1;
    if (i < argc && strcmp(argv[i], "--help") == 0)
        return help();
    if (i < argc && strcmp(argv[i], "--version") == 0)
        return version();
    if (i < argc && strncmp(argv[i], "-v", 2) == 0) {
        if (argv[i][2] != '\0')
            i += 1;
        else if (i + 1 < argc)
            i += 2;
        else
            return usage();
    }
    if (i < argc && strcmp(argv[i], "-a") == 0) {
        if (argc - i > 2)
            return usage();
        return list_all(argc - i == 2 ? argv[i + 1] : "/");
    }
    if (i < argc && strcmp(argv[i], "--") == 0)
        i += 1;
    if (i >= argc)
        return usage();
    const struct name *e = lookup(argv[i]);
    if (e == NULL) {
        fprintf(stderr, "getconf: Unrecognized variable `%s'\n", argv[i]);
        return 2;
    }
    int operands = argc - i;
    if (operands != (e->kind == PC ? 2 : 1))
        return usage();
    if (e->kind == CS) {
        print_confstr(e->constant);
        putchar('\n');
        return 0;
    }
    long v;
    if (e->kind == SC) {
        v = sysconf(e->constant);
    } else {
        errno = 0;
        v = pathconf(argv[i + 1], e->constant);
        if (v == -1 && errno != 0) {
            fprintf(stderr, "getconf: pathconf: %s: %s\n", argv[i + 1], strerror(errno));
            return 3;
        }
    }
    print_long(e, v, "undefined");
    putchar('\n');
    return 0;
}
